#include <bits/stdc++.h>
using namespace std;

static const int MOD=998244353;
int main() {
	// your code goes here
	int t;
	 cin>>t;
	 
	 while(t--){
	      int n;
	      cin>>n;
	      
	      
	      vector<int> a(n+1);
	      vector<vector<int>>pos(n+1);
	      
	      for(int i=1;i<=n;i++){
	          cin>>a[i];
	          pos[a[i]].push_back(i);
	      }
	      vector<int> dp(n+1,0),ndp(n+1,0);
	      dp[0]=1;
	      
	      auto valid=[&](int v,int l,bool putLeft)->bool{
	          int r=v-l;
	          int where=putLeft ? l:n-r+1;
	          
	          for(int i:pos[v]){
	              int prefCount=min(l,i)+max(0,r-(n-i));
	              int prefNeed=(i+1)/2;
	              
	              bool okPref=(where<=i && prefCount==prefNeed);
	              
	              int suffCount=min(r,n-i+1)+max(0,l-(i-1));
	              int suffNeed=(n-i+2)/2;
	              
	              bool oksuff=(where>=i && suffCount==suffNeed);
	              
	              if(!okPref && !oksuff)
	                return false;
	          }
	          return true;
	      };
	      for(int v=1;v<=n;v++){
	          fill(ndp.begin(),ndp.end(),0);
	          
	          for(int lprev=0;lprev<=v-1;lprev++){
	              if(dp[lprev]==0){
	                  continue;
	              }
	              int l=lprev+1;
	              if(valid(v,l,true)){
	                  ndp[l]+=dp[lprev];
	                  
	                  if(ndp[l]>=MOD)
	                     ndp[l]-=MOD;
	              }
	              if(v<n){
	                  l=lprev;
	                  
	                  if(valid(v,l,false)){
	                      ndp[l]+=dp[lprev];
	                      
	                      if(ndp[l]>=MOD)
	                         ndp[l]-=MOD;
	                  }
	              }
	          }
	          
	          dp.swap(ndp);
	      }
	      int ans=0;
	      
	      for(int x:dp){
	          ans+=x;
	          if(ans>=MOD)
	            ans-=MOD;
	            
	      }
	      cout<<ans<<'\n';
	 }

}
